argument_once:
float next(inout float x){float y=x; x=x+1; return y;}
struct F { float a; float b; };
float4 main(float4 t:TEXCOORD0):COLOR {float x=t.x; F f={next(x),next(x)}; return float4(f.a,f.b,x,1);}

constructor_as_argument:
struct A { float2 uv; }; struct B { A inner; float gain; };
float2 consume(B b){return b.inner.uv*b.gain;}
float4 main(float4 t:TEXCOORD0):COLOR {A a={t.xy};return float4(consume(B(a,t.z)),0,1);}
